-- Fictional fixtures in the disposable validation database only.
begin;
create schema booking_test;
create function booking_test.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'ok - booking: %',label;end$$;
create function booking_test.fails(command text,code text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected %, got %: %',label,code,sqlstate,sqlerrm;end if;raise notice 'ok - booking: % (refused)',label;return;end;raise exception 'FAIL: % was permitted',label;end$$;
grant usage on schema booking_test to anon,authenticated,service_role;grant execute on all functions in schema booking_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ba000000-0000-4000-8000-000000000001','booking-owner@example.test'),('ba000000-0000-4000-8000-000000000002','booking-other@example.test'),('ba000000-0000-4000-8000-000000000003','booking-member@example.test');
insert into public.organizations(id,name,slug) values('ba000000-0000-4000-8000-000000000011','Booking A','booking-a'),('ba000000-0000-4000-8000-000000000012','Booking B','booking-b');
insert into public.organization_members(organization_id,user_id,role,status) values('ba000000-0000-4000-8000-000000000011','ba000000-0000-4000-8000-000000000001','owner','active'),('ba000000-0000-4000-8000-000000000012','ba000000-0000-4000-8000-000000000002','owner','active'),('ba000000-0000-4000-8000-000000000011','ba000000-0000-4000-8000-000000000003','member','active');
insert into public.websites(id,organization_id,name,status,live_url) values('ba000000-0000-4000-8000-000000000021','ba000000-0000-4000-8000-000000000011','Booking A','live','https://booking-a.example.test'),('ba000000-0000-4000-8000-000000000022','ba000000-0000-4000-8000-000000000012','Booking B','live','https://booking-b.example.test');
insert into public.subscriptions(organization_id,website_id,plan_id,status,current_period_end) select organization_id,id,(select id from public.plans where code=case when w.name='Booking A' then 'care' else 'basic' end),'active',now()+interval '30 days' from public.websites w where id::text like 'ba%';
insert into public.website_contact_settings(website_id,organization_id,notification_email,allowed_origins,enabled) select id,organization_id,'owner@example.test',array[live_url],true from public.websites where id::text like 'ba%';
select booking_test.ok(vigil.booking_entitled('ba000000-0000-4000-8000-000000000021'),'Care eligible');
select booking_test.ok(not vigil.booking_entitled('ba000000-0000-4000-8000-000000000022'),'Basic ineligible');
select booking_test.ok(not vigil.booking_hours_valid('[{"day":null,"start":"09:00","end":"17:00"}]'),'null hours rejected');
select booking_test.ok(not vigil.booking_hours_valid('[{"day":1,"start":"09:00","end":"17:00"},{"day":1,"start":"16:00","end":"18:00"}]'),'overlapping hours rejected');
select booking_test.ok(not vigil.booking_hours_valid('[{"day":1,"start":"25:00","end":"26:00"}]'),'invalid clock rejected');
select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','ba000000-0000-4000-8000-000000000001',true);set local role authenticated;
select booking_test.ok(public.booking_eligible('ba000000-0000-4000-8000-000000000021'),'member-scoped eligibility');
select public.save_booking_resource('ba000000-0000-4000-8000-000000000021','{"id":"ba000000-0000-4000-8000-000000000031","name":"Consultant","active":true,"hours":[{"day":0,"start":"00:00","end":"23:45"},{"day":1,"start":"00:00","end":"23:45"},{"day":2,"start":"00:00","end":"23:45"},{"day":3,"start":"00:00","end":"23:45"},{"day":4,"start":"00:00","end":"23:45"},{"day":5,"start":"00:00","end":"23:45"},{"day":6,"start":"00:00","end":"23:45"}]}');
select public.save_booking_service('ba000000-0000-4000-8000-000000000021','{"id":"ba000000-0000-4000-8000-000000000041","resourceId":"ba000000-0000-4000-8000-000000000031","name":"Consultation","description":"","duration":30,"bufferBefore":15,"bufferAfter":15,"mode":"instant","active":true}');
select public.save_booking_service('ba000000-0000-4000-8000-000000000021','{"id":"ba000000-0000-4000-8000-000000000042","resourceId":"ba000000-0000-4000-8000-000000000031","name":"Request consultation","description":"","duration":30,"bufferBefore":15,"bufferAfter":15,"mode":"approval","active":true}');
select booking_test.fails($q$select public.configure_bookings('ba000000-0000-4000-8000-000000000021','{"timeZone":"UTC","enabled":true,"acknowledgeAvailability":true,"minimumNotice":0,"horizonDays":180,"changeNotice":120}')$q$,'22023','eligible plan does not activate unverified component');
select booking_test.fails($q$select public.configure_bookings('ba000000-0000-4000-8000-000000000021','{"timeZone":"UTC","enabled":false,"acknowledgeAvailability":false,"minimumNotice":0,"horizonDays":180,"changeNotice":120}',true)$q$,'42501','owner cannot assert site compatibility');
select booking_test.fails($q$select public.configure_bookings('ba000000-0000-4000-8000-000000000021','{"timeZone":"UTC","enabled":null,"acknowledgeAvailability":true,"minimumNotice":0,"horizonDays":180,"changeNotice":120}')$q$,'22023','null activation rejected');
select booking_test.fails($q$select public.save_booking_resource('ba000000-0000-4000-8000-000000000022','{"name":"Forged","active":true,"hours":[]}')$q$,'42501','cross-tenant setup refused');
reset role;update public.booking_settings set component_ready=true where website_id='ba000000-0000-4000-8000-000000000021';set local role authenticated;
select public.configure_bookings('ba000000-0000-4000-8000-000000000021','{"timeZone":"America/New_York","enabled":true,"acknowledgeAvailability":true,"minimumNotice":0,"horizonDays":180,"changeNotice":120}');
reset role;select set_config('request.jwt.claim.sub','ba000000-0000-4000-8000-000000000003',true);set local role authenticated;
select booking_test.fails($q$select public.save_booking_service('ba000000-0000-4000-8000-000000000021','{}')$q$,'42501','member cannot manage services');
select booking_test.fails($q$select vigil.booking_transition(null,'cancel',1)$q$,'42501','transition helper cannot bypass role checks');
select booking_test.fails($q$select public.booking_public_config('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test')$q$,'42501','authenticated caller cannot call server booking API');
reset role;select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
select booking_test.ok(public.booking_public_config('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test')->>'timeZone'='America/New_York','public config only includes approved website');
select booking_test.fails($q$select public.booking_public_config('ba000000-0000-4000-8000-000000000021','https://wrong.example.test')$q$,'42501','wrong origin refused');
select set_config('booking_test.start',((current_date+3)+time '15:00')::timestamptz::text,true);
select booking_test.ok(jsonb_array_length(public.booking_public_slots('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000041',current_date+3))>0,'real UTC availability returned');
select set_config('booking_test.booking',(public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000041',current_setting('booking_test.start')::timestamptz,'ba000000-0000-4000-8000-000000000051',repeat('a',64),repeat('b',64),'{"name":"Test visitor","email":"visitor@example.test"}','')->>'id'),true);
select booking_test.ok(public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000041',current_setting('booking_test.start')::timestamptz,'ba000000-0000-4000-8000-000000000051',repeat('a',64),repeat('b',64),'{"name":"Test visitor","email":"visitor@example.test"}','')->>'id'=current_setting('booking_test.booking'),'retry returns same appointment');
select booking_test.ok((select count(*)=1 from public.leads where source='booking'),'retry creates no duplicate lead');
select booking_test.ok((select count(*)=0 from public.lead_notifications where organization_id='ba000000-0000-4000-8000-000000000011'),'booking never silently sends customer or staff email');
select booking_test.fails($q$select public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000041',current_setting('booking_test.start')::timestamptz,'ba000000-0000-4000-8000-000000000051',repeat('c',64),repeat('b',64),'{"name":"Test visitor","email":"visitor@example.test"}','')$q$,'23505','changed retry refused');
select booking_test.fails($q$select public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000041',current_setting('booking_test.start')::timestamptz+interval '30 minutes','ba000000-0000-4000-8000-000000000052',repeat('a',64),repeat('b',64),'{"name":"Other","email":"other@example.test"}','')$q$,'23P01','buffers prevent overlap');
select booking_test.fails($q$select public.manage_guest_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test',current_setting('booking_test.booking')::uuid,repeat('c',64),'read')$q$,'42501','appointment id alone cannot authorize management');
select booking_test.ok(not(public.manage_guest_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test',current_setting('booking_test.booking')::uuid,repeat('b',64),'read') ? 'contact'),'guest receipt excludes private customer fields');
-- Two approval requests may share a candidate slot; acceptance rechecks capacity.
select set_config('booking_test.request1',(public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000042',current_setting('booking_test.start')::timestamptz+interval '2 hours','ba000000-0000-4000-8000-000000000053',repeat('d',64),repeat('b',64),'{"name":"Request one","email":"one@example.test"}','')->>'id'),true);
select set_config('booking_test.request2',(public.create_public_booking('ba000000-0000-4000-8000-000000000021','https://booking-a.example.test','ba000000-0000-4000-8000-000000000042',current_setting('booking_test.start')::timestamptz+interval '2 hours','ba000000-0000-4000-8000-000000000054',repeat('e',64),repeat('c',64),'{"name":"Request two","email":"two@example.test"}','')->>'id'),true);
reset role;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','ba000000-0000-4000-8000-000000000001',true);set local role authenticated;
select public.manage_booking(current_setting('booking_test.request1')::uuid,'confirm',1);
select booking_test.fails($q$select public.manage_booking(current_setting('booking_test.request2')::uuid,'confirm',1)$q$,'23P01','approval cannot double book');
select booking_test.fails($q$select public.manage_booking(current_setting('booking_test.request1')::uuid,'cancel',1)$q$,'40001','stale action rejected');
select booking_test.fails($q$select public.manage_booking(current_setting('booking_test.request1')::uuid,'complete',2)$q$,'22023','future appointment cannot be completed');
select booking_test.fails($q$select public.manage_booking(current_setting('booking_test.request1')::uuid,'reschedule',2,current_setting('booking_test.start')::timestamptz)$q$,'23P01','failed reschedule retains old reservation');
select booking_test.fails($q$select public.configure_bookings('ba000000-0000-4000-8000-000000000021','{"timeZone":"UTC","enabled":false,"acknowledgeAvailability":false,"minimumNotice":0,"horizonDays":180,"changeNotice":120}')$q$,'22023','timezone changes cannot reinterpret open appointments');
