reset role;
select booking_test.fails($q$update public.appointments set status='confirmed' where id=current_setting('booking_test.request2')::uuid$q$,'23P01','database exclusion constraint independently prevents double booking');
update public.appointments set request_expires_at=now()-interval '1 minute' where id=current_setting('booking_test.request2')::uuid;
select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
