select booking_test.ok(public.expire_booking_requests()=0,'expiry is idempotent');
reset role;update public.subscriptions set status='canceled' where website_id='ba000000-0000-4000-8000-000000000021';select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
