select booking_test.ok((select count(*)>=5 from public.appointment_events),'immutable lifecycle evidence retained');
-- Offset-boundary days: no invented wall times, distinct instants during the repeated hour.
select booking_test.ok(not vigil.booking_window_free('ba000000-0000-4000-8000-000000000031','2027-03-14T06:45:00Z',30,0,0,null,'2027-03-13T00:00:00Z'),'spring-forward crossing is not offered');
select booking_test.ok(vigil.booking_window_free('ba000000-0000-4000-8000-000000000031','2027-11-07T05:00:00Z',30,0,0,null,'2027-11-06T00:00:00Z') and vigil.booking_window_free('ba000000-0000-4000-8000-000000000031','2027-11-07T06:00:00Z',30,0,0,null,'2027-11-06T00:00:00Z'),'fall-back repeated hour has distinct valid instants');
